#!/usr/bin/env bash
# ---------------------------------------------------------------------------
# patch-generic-pit.sh
#   Pit scouting for seasons without their own forms (the "notes" seasons)
#   becomes a real form instead of one notes box:
#   1. Scoring capability: a text box
#   2. Mobility: drivetrain (+ which swerve / describe other), drivetrain
#      gearing, robot weight with bumpers and battery. No trench or bump.
#   3. Spares: Swerve modules is the only preset; anything else is an Other
#      row added with the plus
#   4. Batteries, 5. Photo, 6. Notes: as on the 2026 form
#
# Stored on the existing pitNotes rows (new optional fields), so pit notes
# already written are kept and show up as the form's Robot notes. The pit
# page gets Not scouted / Partially scouted / Scouted, like 2026. Complete =
# scoring capability, drivetrain, robot weight and at least one battery.
# Practice mode applies. The team view and the notes export show the new
# fields. 2026 is untouched.
#
# Needs patch-pit-tweaks.sh and patch-practice-mode.sh applied first.
#
# Every edit is checked before any file is written, so a mismatch stops the
# patch with nothing half-applied. CRLF checkouts are handled.
# ---------------------------------------------------------------------------
set -euo pipefail
[[ -f convex/pit.ts ]] || { echo "ERROR: run from the repo root" >&2; exit 1; }
say() { printf '\n\033[1;36m>> %s\033[0m\n' "$*"; }

if grep -qF 'scoringText' convex/schema.ts; then
  echo "patch-generic-pit already applied."
  exit 0
fi
if ! grep -qF 'lib/practice' convex/notes.ts; then
  echo "ERROR: run patch-pit-tweaks.sh and patch-practice-mode.sh first." >&2
  exit 1
fi

# Working files live in the repo root, not /tmp: on Windows, Git Bash's /tmp
# is not where bun looks for a "/tmp/..." path written inside a script.
JSON_FILE=".patch-generic-pit.json"
MJS_FILE=".patch-generic-pit.mjs"
trap 'rm -f "$JSON_FILE" "$MJS_FILE"' EXIT

say "Applying patch-generic-pit"
cat > "$JSON_FILE" <<'PATCH_EDITS_JSON'
