s scouted${partial > 0 ? `, ${partial} partially` : \"\"}. Tap a team to scout it.`\n      }\n    >\n      <div className=\"flex flex-wrap items-center gap-2\">\n        {FILTERS.map((f) => (\n          <Button key={f.value} size=\"sm\"\n            variant={filter === f.value ? \"default\" : \"outline\"}\n            onClick={() => setFilter(f.value)}>\n            {f.label}\n          </Button>\n        ))}\n        <Input className=\"ml-auto max-w-48\" placeholder=\"Find a team\" inputMode=\"numeric\"\n          value={search} onChange={(e) => setSearch(e.target.value)} />\n      </div>\n\n      {teams === undefined ? (\n        <p className=\"text-muted-foreground text-sm\">Loading…</p>\n      ) : shown.length === 0 ? (\n        <p className=\"text-muted-foreground rounded-lg border border-dashed p-8 text-center text-sm\">\n          {filter === \"todo\" && total > 0\n            ? partial > 0\n              ? \"Every team has been visited. Partially scouted ones still need finishing.\"\n              : \"Every team has been scouted.\"\n            : \"Nothing matches.\"}\n        </p>\n      ) : (\n        <div className=\"grid grid-cols-2 gap-3 sm:grid-cols-3 lg:grid-cols-4\">\n          {shown.map((team) => (\n            <button key={team.teamId}\n              onClick={() => void navigate(`/pit/${team.number}`)}\n              className={[\n                \"flex min-h-24 flex-col justify-between rounded-lg border p-3 text-left transition-colors\",\n                team.pitStatus === \"complete\"\n                  ? \"bg-primary/5 border-primary/40\"\n                  : team.pitStatus === \"partial\"\n                    ? \"border-dashed border-primary/40 hover:bg-accent/50\"\n                    : \"hover:bg-accent/50\",\n              ].join(\" \")}>\n              <span className=\"text-2xl font-semibold tabular-nums\">{team.number}</span>\n              <span className=\"text-muted-foreground truncate text-xs\">{team.nickname}</span>\n              <Badge className=\"mt-1 w-fit\"\n                variant={team.pitStatus === \"complete\" ? \"default\" : team.pitStatus === \"partial\" ? \"secondary\" : \"outline\"}>\n                {GENERIC_PIT_LABELS[team.pitStatus]}\n              </Badge>\n            </button>\n          ))}\n        </div>\n      )}\n    </PageShell>\n  );\n}\n"
